cd /workspace && cat > src/ledger.ts <<'EOF'
export interface Receipt { id: number; tenant: string; key: string; cents: number }

export class Ledger {
  readonly entries: Receipt[] = [];

  /** First committed receipt per tenant, then per key: idempotency is scoped by tenant and key. */
  private readonly index = new Map<string, Map<string, Receipt>>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // Replay/conflict check. There is no await between this check and the commit
    // below, so the whole check-and-commit sequence runs to completion inside a
    // single synchronous step and is atomic with respect to other concurrent
    // apply() calls (they serialize in call order). Concurrent duplicate calls
    // therefore all observe the same committed state.
    const existing = this.index.get(tenant)?.get(key);
    if (existing !== undefined) {
      if (existing.cents === cents) {
        // Equal-amount replay: return the original receipt, no additional debit.
        return existing;
      }
      // Same tenant/key reused with a different amount: fail without debiting.
      throw new Error('key conflict');
    }

    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);

    let byKey = this.index.get(tenant);
    if (byKey === undefined) {
      byKey = new Map<string, Receipt>();
      this.index.set(tenant, byKey);
    }
    byKey.set(key, receipt);

    return receipt;
  }
}
EOF
cat > src/service.ts <<'EOF'
import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate before any ledger or transport action.
    if (
      typeof tenant !== 'string' || tenant.length === 0 ||
      typeof key !== 'string' || key.length === 0 ||
      !Number.isInteger(cents) || cents <= 0 ||
      !Number.isInteger(attempts) || attempts < 1 || attempts > 5
    ) {
      throw new Error('invalid payment');
    }

    // Receipt of the committed debit. Acquired at most once per call: the
    // acknowledgement retries below must forward this same receipt, so a
    // retried ack can never look like a second debit. Ledger.apply is itself
    // idempotent per tenant+key (replays return the original receipt; a
    // different amount for the same tenant/key throws 'key conflict').
    let receipt: Receipt | undefined;

    for (let n = 0; n < attempts; n++) {
      try {
        if (receipt === undefined) {
          receipt = await this.ledger.apply(tenant, key, cents);
        }

        // The debit is committed; acknowledgement is external and may fail with
        // Transient after commit. Forward the same receipt on every attempt.
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        // Retry only Transient, up to `attempts` total tries; rethrow anything
        // else immediately, and rethrow the original error once exhausted.
        if (!(error instanceof Transient) || n === attempts - 1) throw error;
      }
    }

    // Unreachable: attempts >= 1, so the first iteration returns or throws.
    throw new Error('invalid payment');
  }
}
EOF
