const assert = require('node:assert/strict');

const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

class RecordingAck {
  constructor(failures = 0, failureError = null) {
    this.calls = [];
    this.remaining = failures;
    this.failureError = failureError === null ? new Transient('ack flake') : failureError;
  }
  async acknowledge(receipt) {
    this.calls.push(receipt);
    if (this.remaining-- > 0) throw this.failureError;
  }
}

class FlakyLedger extends Ledger {
  constructor() { super(); this.flaky = 2; }
  async apply(tenant, key, cents) {
    if (this.flaky-- > 0) throw new Transient('ledger flake');
    return super.apply(tenant, key, cents);
  }
}

async function main() {
  // Sequential duplicate: equal amount replays the original receipt, one debit.
  {
    const ledger = new Ledger();
    const ack = new RecordingAck();
    const service = new PaymentService(ledger, ack);
    const first = await service.pay('shop', 'sale', 123);
    const second = await service.pay('shop', 'sale', 123);
    assert.ok(first === second, 'replay must return the original receipt');
    assert.equal(ledger.entries.length, 1);
    assert.deepEqual(first, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
  }

  // Key conflict: same tenant/key, different amount, no extra debit, no ack.
  {
    const ledger = new Ledger();
    const ack = new RecordingAck();
    const service = new PaymentService(ledger, ack);
    await service.pay('shop', 'sale', 123);
    await assert.rejects(service.pay('shop', 'sale', 999), /key conflict/);
    assert.equal(ledger.entries.length, 1);
    assert.equal(ack.calls.length, 1);
  }

  // Concurrent duplicates: all agree on one receipt, one debit.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, new RecordingAck());
    const [a, b, c] = await Promise.all([
      service.pay('cc', 'k', 50),
      service.pay('cc', 'k', 50),
      service.pay('cc', 'k', 50),
    ]);
    assert.ok(a === b && b === c, 'concurrent duplicates share one receipt');
    assert.equal(ledger.entries.length, 1);
  }

  // Concurrent conflict: first call commits, different amount rejects, no extra debit.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, new RecordingAck());
    const outcome = await Promise.allSettled([
      service.pay('cc', 'k', 50),
      service.pay('cc', 'k', 99),
    ]);
    assert.equal(outcome[0].status, 'fulfilled');
    assert.equal(outcome[1].status, 'rejected');
    assert.match(String(outcome[1].reason), /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }

  // Transient acks are retried with the same receipt; debit happens once.
  {
    const ledger = new Ledger();
    const ack = new RecordingAck(4); // 4 transients, 5th attempt succeeds
    const service = new PaymentService(ledger, ack);
    const receipt = await service.pay('retry', 'key', 7, 5);
    assert.equal(ledger.entries.length, 1);
    assert.equal(ack.calls.length, 5);
    assert.ok(ack.calls.every(c => c === receipt), 'every try forwards the same receipt');
  }

  // Default attempts = 3: two transients then success.
  {
    const ledger = new Ledger();
    const ack = new RecordingAck(2);
    const service = new PaymentService(ledger, ack);
    const receipt = await service.pay('d', 'k', 3);
    assert.equal(ack.calls.length, 3);
    assert.equal(ledger.entries.length, 1);
    assert.ok(ack.calls.every(c => c === receipt));
  }

  // Exhausted retries rethrow the final Transient instance; only `attempts` tries.
  {
    const ledger = new Ledger();
    const boom = new Transient('final flake');
    const ack = new RecordingAck(Number.MAX_SAFE_INTEGER, boom);
    const service = new PaymentService(ledger, ack);
    await assert.rejects(service.pay('ex', 'k', 10, 2), err => err === boom);
    assert.equal(ack.calls.length, 2);
    assert.ok(ack.calls[0] === ack.calls[1]);
    assert.equal(ledger.entries.length, 1);
  }

  // Non-Transient failures are not retried; the original error is preserved.
  {
    const ledger = new Ledger();
    const permanent = new Error('permanent');
    const ack = new RecordingAck(Number.MAX_SAFE_INTEGER, permanent);
    const service = new PaymentService(ledger, ack);
    await assert.rejects(service.pay('perm', 'k', 10, 3), err => err === permanent);
    assert.equal(ack.calls.length, 1);
    assert.equal(ledger.entries.length, 1);
  }

  // Transient from the ledger (pre-commit) is retried too, still one debit.
  {
    const ledger = new FlakyLedger();
    const ack = new RecordingAck();
    const service = new PaymentService(ledger, ack);
    const receipt = await service.pay('flaky', 'k', 42);
    assert.equal(ledger.entries.length, 1);
    assert.equal(ack.calls.length, 1);
    assert.ok(ack.calls[0] === receipt);
  }

  // Validation happens before any ledger or transport action, including when a
  // conflicting entry already exists for the tenant/key.
  {
    const ledger = new Ledger();
    const ack = new RecordingAck();
    const service = new PaymentService(ledger, ack);
    await service.pay('tenant', 'key', 10);
    const badCases = [
      ['', 'key', 10],
      ['tenant', '', 10],
      ['tenant', ' ', 0],
      ['tenant', 'key', -1],
      ['tenant', 'key', 1.5],
      ['tenant', 'key', NaN],
      ['tenant', 'key', 10, 0],
      ['tenant', 'key', 10, 6],
      ['tenant', 'key', 10, 2.5],
      ['tenant', 'key', 10, NaN],
      [123, 'key', 10],
      ['tenant', 123, 10],
    ];
    for (const args of badCases) {
      await assert.rejects(service.pay(...args), /invalid payment/, `case: ${JSON.stringify(args)}`);
    }
    assert.equal(ledger.entries.length, 1, 'rejected input must not debit');
    assert.equal(ack.calls.length, 1, 'rejected input must not acknowledge');
  }

  // Idempotency is scoped per tenant: same key under different tenants are independent.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, new RecordingAck());
    await service.pay('a', 'shared', 10);
    const b = await service.pay('b', 'shared', 20);
    assert.deepEqual(b, { id: 2, tenant: 'b', key: 'shared', cents: 20 });
    assert.equal(ledger.entries.length, 2);
  }

  // Boundary: attempts = 1 fails fast on the first Transient.
  {
    const ledger = new Ledger();
    const boom = new Transient('once');
    const ack = new RecordingAck(Number.MAX_SAFE_INTEGER, boom);
    const service = new PaymentService(ledger, ack);
    await assert.rejects(service.pay('one', 'k', 1, 1), err => err === boom);
    assert.equal(ack.calls.length, 1);
    assert.equal(ledger.entries.length, 1);
  }
}

module.exports = main();
EOF
